SELECT c.cursor, c.entity_id AS tender_id, c.version_seq AS seq, c.op, c.changed_at, n.id AS nid, n.ingested_at AS n_ingested_at, t.created_at, t.source, t.current_seq, EXISTS (SELECT 1 FROM tender_versions v2 CROSS JOIN notices n2 ON n2.id = v2.caused_by_notice_id WHERE v2.tender_id = c.entity_id AND n2.id < n.id AND +n2.source = 'doe') AS doe_before, EXISTS (SELECT 1 FROM tender_versions v2 CROSS JOIN notices n2 ON n2.id = v2.caused_by_notice_id WHERE v2.tender_id = c.entity_id AND n2.id < n.id AND +n2.source = 'ted') AS ted_before, (SELECT MIN(n2.id) FROM tender_versions v2 CROSS JOIN notices n2 ON n2.id = v2.caused_by_notice_id WHERE v2.tender_id = c.entity_id AND +n2.source = 'doe') AS doe_min_nid, (SELECT MIN(c2.cursor) FROM changes c2 WHERE c2.entity_kind = 'tender' AND c2.entity_id = c.entity_id AND c2.version_seq IS NULL AND c2.op = 'changed' AND c2.changed_at = c.changed_at AND c2.cursor > c.cursor AND c2.cursor <= 958848408) AS seqless_cursor FROM changes c CROSS JOIN tender_versions v ON v.tender_id = c.entity_id AND v.seq = c.version_seq CROSS JOIN notices n ON n.id = v.caused_by_notice_id CROSS JOIN tenders t ON t.id = c.entity_id WHERE c.cursor > 958845037 AND c.cursor <= 958848408 AND +c.entity_kind = 'tender' AND c.version_seq IS NOT NULL AND +n.source = 'ted' AND EXISTS (SELECT 1 FROM tender_versions v3 CROSS JOIN notices n3 ON n3.id = v3.caused_by_notice_id WHERE v3.tender_id = c.entity_id AND +n3.source = 'doe') ORDER BY c.cursor LIMIT 2000
